-- Analytical View: Expression Summary---- Purpose:-- Summarize descriptive gene expression statistics-- within each histological subtype.---- Grain:-- One row per histological subtype and gene.---- Source:-- analytical.vw_expression_by_histologyCREATE OR REPLACE VIEW analytical.vw_expression_summary ASSELECT    histological_type,    gene,    COUNT(*) AS sample_count,    ROUND(        AVG(expression_level)::numeric,        4    ) AS mean_expression,    ROUND(        PERCENTILE_CONT(0.5)        WITHIN GROUP (ORDER BY expression_level)::numeric,        4    ) AS median_expression,    MIN(expression_level) AS min_expression,    MAX(expression_level) AS max_expressionFROM analytical.vw_expression_by_histologyGROUP BY    histological_type,    gene;